-- Source: database/functions/eshop_orders/replacement_invoice_preparation.sql
-- A replacement has already atomically canceled its old allocation. Provider
-- preparation retries keep the new allocation and fence invoice POST separately.
CREATE TABLE IF NOT EXISTS eshop.replacement_invoice_preparations(
 command_id uuid PRIMARY KEY,
 order_id bigint NOT NULL UNIQUE REFERENCES eshop.orders(id) ON DELETE CASCADE,
 state text NOT NULL CHECK(state IN('claimed','retryable','unknown','complete')),
 dispatch_started boolean NOT NULL DEFAULT false,
 lease_token uuid,
 lease_until timestamptz,
 attempts integer NOT NULL DEFAULT 0,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
ALTER TABLE eshop.replacement_invoice_preparations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE eshop.replacement_invoice_preparations FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.claim_replacement_invoice_preparation(p_order bigint,p_command uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE attempt eshop.replacement_invoice_preparations;receipt jsonb;token uuid:=extensions.gen_random_uuid();state text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 SELECT o.state INTO state FROM eshop.orders o WHERE o.id=p_order FOR UPDATE;
 SELECT r.response INTO receipt FROM public.client_mutation_receipts r
  WHERE r.command_id=p_command AND r.command_name='inventory.order.replace' AND r.status='completed'
  AND r.response->>'status'='applied' AND (r.response#>>'{data,order,id}')::bigint=p_order;
 IF receipt IS NULL AND NOT EXISTS(SELECT 1 FROM eshop.replacement_invoice_preparations a
  WHERE a.command_id=p_command AND a.order_id=p_order) THEN
  RAISE insufficient_privilege USING MESSAGE='replacement receipt unavailable'; END IF;
 IF state IN('ordered','paid') THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF state IS DISTINCT FROM 'preparing_payment' THEN RETURN jsonb_build_object('status','closed'); END IF;
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order
  AND q.data->>'fakturoid_pending'='true' FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='invoice preparation claim unavailable'; END IF;
 SELECT * INTO attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 IF NOT FOUND THEN
  -- Legacy pending receipts may already have dispatched an invoice. They are
  -- lookup-only; absence in one GET is not proof that a POST never executed.
  INSERT INTO eshop.replacement_invoice_preparations(command_id,order_id,state,dispatch_started)
   VALUES(p_command,p_order,'retryable',receipt#>>'{data,paymentPreparationPolicy}' IS DISTINCT FROM 'leased_keep_pending');
  SELECT * INTO STRICT attempt FROM eshop.replacement_invoice_preparations WHERE command_id=p_command FOR UPDATE;
 END IF;
 IF attempt.order_id<>p_order THEN RAISE insufficient_privilege USING MESSAGE='invoice order mismatch'; END IF;
 IF attempt.state='complete' THEN RETURN jsonb_build_object('status','complete'); END IF;
 IF attempt.lease_until>clock_timestamp() THEN RETURN jsonb_build_object('status','busy'); END IF;
 UPDATE eshop.replacement_invoice_preparations SET state='claimed',lease_token=token,
  lease_until=clock_timestamp()+interval '180 seconds',attempts=attempts+1,updated_at=clock_timestamp()
 WHERE command_id=p_command;
 RETURN jsonb_build_object('status','claimed','token',token,'allowCreate',NOT attempt.dispatch_started);
END $$;
REVOKE ALL ON FUNCTION public.claim_replacement_invoice_preparation(bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_replacement_invoice_preparation(bigint,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.mark_replacement_invoice_dispatch(p_order bigint,p_command uuid,p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 UPDATE eshop.replacement_invoice_preparations SET dispatch_started=true,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order AND lease_token=p_token AND lease_until>clock_timestamp()
  AND state='claimed' AND NOT dispatch_started;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='invoice dispatch lease unavailable'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.mark_replacement_invoice_dispatch(bigint,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mark_replacement_invoice_dispatch(bigint,uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.release_replacement_invoice_preparation(p_order bigint,p_command uuid,p_token uuid,p_not_created boolean DEFAULT false)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_not_created IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invoice outcome required'; END IF;
 UPDATE eshop.replacement_invoice_preparations SET
  dispatch_started=dispatch_started AND NOT p_not_created,
  state=CASE WHEN dispatch_started AND NOT p_not_created THEN 'unknown' ELSE 'retryable' END,
  lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order AND lease_token=p_token AND state='claimed';
 RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION public.release_replacement_invoice_preparation(bigint,uuid,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_replacement_invoice_preparation(bigint,uuid,uuid,boolean) TO service_role;

CREATE OR REPLACE FUNCTION public.complete_replacement_invoice_preparation(p_order bigint,p_command uuid,p_token uuid,p_variable_symbol bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE symbol bigint;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
 PERFORM 1 FROM public.email_messages q WHERE q.code='TICKET_ORDER_CONFIRMATION'
  AND q.data->>'command_id'=p_command::text AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order FOR UPDATE;
 PERFORM 1 FROM eshop.replacement_invoice_preparations WHERE command_id=p_command AND order_id=p_order
  AND lease_token=p_token AND lease_until>clock_timestamp() AND state='claimed' FOR UPDATE;
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='invoice completion lease unavailable'; END IF;
 symbol:=public.complete_fakturoid_ticket_order_v1(p_order,p_command,p_variable_symbol);
 UPDATE eshop.replacement_invoice_preparations SET state='complete',lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE command_id=p_command AND order_id=p_order;
 RETURN symbol;
END $$;
REVOKE ALL ON FUNCTION public.complete_replacement_invoice_preparation(bigint,uuid,uuid,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_replacement_invoice_preparation(bigint,uuid,uuid,bigint) TO service_role;


-- Source: database/functions/blueprint/apply_seat_swap_internal.sql
-- Validate only entities actually participating in this swap before locking
-- their parents, then again once the complete assignment closure is locked.
CREATE OR REPLACE FUNCTION public.check_blueprint_swap_scope_internal(p_occasion bigint,p_spots bigint[])
RETURNS void LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
BEGIN
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion)<>cardinality(p_spots)
  OR EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprints b ON b.id=s.blueprint
   LEFT JOIN eshop.products p ON p.id=s.product LEFT JOIN eshop.product_types pt ON pt.id=p.product_type
   LEFT JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
   LEFT JOIN eshop.orders o ON o.id=i."order" LEFT JOIN eshop.tickets t ON t.id=i.ticket
   WHERE s.id=ANY(p_spots) AND (
    (s.blueprint IS NOT NULL AND b.occasion IS DISTINCT FROM p_occasion)
    OR (s.product IS NOT NULL AND (p.occasion IS DISTINCT FROM p_occasion OR pt.occasion IS DISTINCT FROM p_occasion))
    OR (s.order_product_ticket IS NOT NULL AND (o.occasion IS DISTINCT FROM p_occasion OR t.occasion IS DISTINCT FROM p_occasion)))) THEN
  RAISE insufficient_privilege USING MESSAGE='swap assignment scope unavailable'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.check_blueprint_swap_scope_internal(bigint,bigint[]) FROM PUBLIC,anon,authenticated,service_role;

-- Capture the actual financial owner's effects, never a second price calculation.
-- Preview callers roll this work back; confirmed command callers retain it only
-- when its digest matches the effects previously approved by the operator.
CREATE OR REPLACE FUNCTION public.apply_blueprint_seat_swap_internal(p_first bigint,p_second bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE occ bigint; left_ids bigint[];right_ids bigint[];ids bigint[];v_order_ids bigint[];
 before_orders jsonb;sides jsonb;revisions jsonb;effects jsonb;facts jsonb;result jsonb;i integer;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_first,p_second);
 IF p_first IS NULL OR p_second IS NULL OR p_first=p_second OR occ IS NULL
  OR (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=occ)<>2
  OR public.can_write_orders(occ) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 left_ids:=public.blueprint_selection_unit_spots_internal(p_first);
 right_ids:=public.blueprint_selection_unit_spots_internal(p_second);
 IF cardinality(left_ids)<>cardinality(right_ids) OR left_ids && right_ids THEN
  RAISE EXCEPTION 'BLUEPRINT_UNIT_SIZE_MISMATCH'; END IF;
 ids:=left_ids||right_ids;
 PERFORM public.check_blueprint_swap_scope_internal(occ,ids);
 PERFORM public.lock_spot_assignment_scope_internal(ids,'{}'::bigint[],true);
 PERFORM public.check_blueprint_swap_scope_internal(occ,ids);
 -- Ticket rows are locked before rechecking used atomic-unit members.
 PERFORM public.check_blueprint_selection_units_internal(ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'revision',layout_revision) ORDER BY id),'[]')
 INTO revisions FROM eshop.blueprints WHERE id IN(SELECT blueprint FROM eshop.spots WHERE id=ANY(ids));
 SELECT array_agg(DISTINCT i."order") INTO v_order_ids FROM eshop.spots s
 JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket WHERE s.id=ANY(ids);
 IF EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprint_seat_bindings b ON b.spot=s.id
  WHERE s.id=ANY(ids) AND (b.blocked OR s.product IS NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp()))) THEN
  RAISE EXCEPTION 'BLUEPRINT_SEAT_PROTECTED'; END IF;
 before_orders:=public.order_payment_snapshot_internal(v_order_ids);
 WITH lifecycle AS MATERIALIZED (SELECT id,state FROM public.blueprint_spot_facts_internal(occ,ids))
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',s.id,'title',s.title,'state',lifecycle.state,'productId',s.product,
  'productTitle',p.title,'orderId',o.id,'ticketId',i.ticket,
  'customer',jsonb_build_object('name',o.data->>'name','surname',o.data->>'surname','email',o.data->>'email')) ORDER BY s.id),'[]'),
 coalesce(jsonb_agg(jsonb_build_object('spot',s.id,'blueprint',s.blueprint,'item',i.id,'ticketState',t.state,
  'product',s.product,'price',p.price,'currency',p.currency_code) ORDER BY s.id),'[]')
 INTO sides,facts FROM eshop.spots s LEFT JOIN eshop.products p ON p.id=s.product
 LEFT JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket LEFT JOIN eshop.tickets t ON t.id=i.ticket
 LEFT JOIN eshop.orders o ON o.id=i."order" LEFT JOIN lifecycle ON lifecycle.id=s.id WHERE s.id=ANY(ids);
 FOR i IN 1..cardinality(left_ids) LOOP PERFORM public.apply_blueprint_seat_pair_locked_internal(left_ids[i],right_ids[i]); END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',id,
  'beforeAmount',(before_orders->id::text->>'amount')::numeric,'afterAmount',price,
  'delta',price-(before_orders->id::text->>'amount')::numeric,'currencyCode',currency_code,
  'beforeState',before_orders->id::text->>'state','afterState',state) ORDER BY id),'[]')
 INTO effects FROM eshop.orders WHERE id=ANY(v_order_ids);
 result:=jsonb_build_object('code',200,'spotIds',to_jsonb(ids),'sourceSpotIds',left_ids,'targetSpotIds',right_ids,
  'blueprints',revisions,'sides',sides,'orders',effects);
 RETURN result||jsonb_build_object('confirmationHash',encode(extensions.digest(convert_to(
  jsonb_build_object('first',p_first,'second',p_second,'result',result,'facts',facts,'beforeOrders',before_orders)::text,'UTF8'),'sha256'),'hex'));
END $$;
REVOKE ALL ON FUNCTION public.apply_blueprint_seat_swap_internal(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/swap_command_internal.sql
CREATE OR REPLACE FUNCTION public.swap_blueprint_seats_command_internal(
 p_first bigint,p_second bigint,p_command_id uuid,p_confirmation jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid();occ bigint;started jsonb;fingerprint text;users uuid[];
 effect jsonb;affected bigint[];result_data jsonb;money jsonb;
BEGIN
 SELECT occasion INTO occ FROM public.client_mutation_receipts
 WHERE command_id=p_command_id AND actor_id=actor AND command_name='inventory.spots.swap';
 IF NOT FOUND THEN SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_first,p_second); END IF;
 IF actor IS NULL OR p_first IS NULL OR p_second IS NULL OR p_first=p_second OR occ IS NULL
  OR public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 fingerprint:=encode(extensions.digest(convert_to((jsonb_build_object('spot1',p_first,'spot2',p_second)
  ||CASE WHEN p_confirmation IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('confirmation',p_confirmation) END)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.spots.swap',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN started->'response';
 END IF;
 IF (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=occ)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='foreign spot swap'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 affected:=CASE WHEN p_confirmation IS NULL THEN ARRAY[p_first,p_second] ELSE
  public.blueprint_selection_unit_spots_internal(p_first)||public.blueprint_selection_unit_spots_internal(p_second) END;
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM eshop.spots s
 JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
 JOIN public.occasion_users ou ON ou.ticket=i.ticket AND ou.occasion=occ WHERE s.id=ANY(affected);
 BEGIN
  effect:=public.apply_blueprint_seat_swap_internal(p_first,p_second);
  IF p_confirmation IS NOT NULL THEN money:=public.project_order_amount_changes_internal(effect->'orders'); END IF;
  IF p_confirmation IS NOT NULL AND
   (effect->>'confirmationHash' IS DISTINCT FROM p_confirmation->>'hash'
    OR effect->'sourceSpotIds' IS DISTINCT FROM p_confirmation->'source'
    OR effect->'targetSpotIds' IS DISTINCT FROM p_confirmation->'target'
    OR effect->'blueprints' IS DISTINCT FROM jsonb_build_array(jsonb_build_object(
     'id',(p_confirmation->>'blueprint')::bigint,'revision',(p_confirmation->>'revision')::bigint))) THEN
   RAISE SQLSTATE 'BP002' USING MESSAGE='confirmed swap changed'; END IF;
 EXCEPTION WHEN SQLSTATE 'BP002' THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SWAP_CHANGED'));
 WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
 WHEN OTHERS THEN
  IF p_confirmation IS NULL THEN RAISE; END IF;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_SWAP_REJECTED'));
 END;
 -- Legacy adapters share the same late guard, not just the scoped UI/MCP RPC.
 IF public.can_write_orders(occ) IS NOT TRUE OR
  (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=occ)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 PERFORM public.check_occasion_writable(occ);
 result_data:=jsonb_build_object('spotIds',jsonb_build_array(p_first,p_second));
 IF p_confirmation IS NOT NULL THEN
  result_data:=result_data||jsonb_build_object('blueprintId',(p_confirmation->>'blueprint')::bigint,
   'layoutRevision',(p_confirmation->>'revision')::bigint,'sourceSpotIds',effect->'sourceSpotIds',
   'targetSpotIds',effect->'targetSpotIds','orders',money);
 END IF;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,occ,'inventory.spots.swap',
  jsonb_build_array(jsonb_build_object('entityType','spot_assignment','entityId',NULL,'operation','update',
   'safeLabel','Spot ticket swap','changedFields',jsonb_build_array('order_product_ticket','product'))),users,result_data);
END $$;
REVOKE ALL ON FUNCTION public.swap_blueprint_seats_command_internal(bigint,bigint,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/seat_swap.sql
CREATE OR REPLACE FUNCTION public.preview_blueprint_seat_swap(p_occasion bigint,p_organization bigint,p_unit bigint,
 p_blueprint bigint,p_first bigint,p_second bigint,p_editor boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE effect jsonb;rows jsonb;money jsonb;ids bigint[];
BEGIN
 IF p_editor IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='swap preview mode required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 -- The shared occasion advisory scope stabilizes membership. Row locks are
 -- acquired by the financial owner after form/order parents, never before them.
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL) THEN
  RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_hold_selection_internal(p_occasion,p_blueprint,ARRAY[p_first,p_second],CASE WHEN p_editor THEN 20000 ELSE 1000 END);
 effect:=public.preview_blueprint_swap(p_first,p_second);
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF (effect->>'code')::int<>200 THEN
  RETURN jsonb_build_object('code',409,'reason',CASE WHEN effect->>'reason'=ANY(ARRAY[
   'BLUEPRINT_UNIT_SIZE_MISMATCH','BLUEPRINT_SELECTION_UNIT_USED','BLUEPRINT_CURRENCY_MISMATCH',
   'STRIPE_ORDER_PRICE_IMMUTABLE','BLUEPRINT_SEAT_PROTECTED','SPOT_HELD'])
   THEN effect->>'reason' ELSE 'BLUEPRINT_SWAP_REJECTED' END);
 END IF;
 SELECT coalesce(jsonb_agg(CASE WHEN p_editor THEN s ELSE s-'customer' END ORDER BY (s->>'spotId')::bigint),'[]')
 INTO rows FROM jsonb_array_elements(effect->'sides') s;
 BEGIN
  money:=public.project_order_amount_changes_internal(effect->'orders');
 EXCEPTION WHEN check_violation THEN
  RETURN jsonb_build_object('code',409,'reason','BLUEPRINT_SWAP_MONEY_UNAVAILABLE');
 END;
 effect:=jsonb_build_object('code',200,'occasionId',p_occasion,'blueprintId',p_blueprint,
  'layoutRevision',effect#>'{blueprints,0,revision}','firstSpotId',p_first,'secondSpotId',p_second,
  'sourceSpotIds',effect->'sourceSpotIds','targetSpotIds',effect->'targetSpotIds',
  'confirmationHash',effect->>'confirmationHash','seats',rows,'orders',money);
 IF octet_length(effect::text)>(CASE WHEN p_editor THEN 8388608 ELSE 1048576 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='swap preview exceeds payload limit'; END IF;
 RETURN effect;
END $$;
REVOKE ALL ON FUNCTION public.preview_blueprint_seat_swap(bigint,bigint,bigint,bigint,bigint,bigint,boolean) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.preview_blueprint_seat_swap(bigint,bigint,bigint,bigint,bigint,bigint,boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.swap_blueprint_seats(p_occasion bigint,p_organization bigint,p_unit bigint,
 p_blueprint bigint,p_first bigint,p_second bigint,p_source_spots bigint[],p_target_spots bigint[],
 p_expected_revision bigint,p_confirmation_hash text,p_command_id uuid,p_editor boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF p_editor IS NULL OR p_command_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0
  OR p_confirmation_hash IS NULL OR p_confirmation_hash!~'^[0-9a-f]{64}$'
  OR coalesce(cardinality(p_source_spots),0)=0 OR coalesce(cardinality(p_target_spots),0)=0
  OR cardinality(p_source_spots)+cardinality(p_target_spots)>(CASE WHEN p_editor THEN 20000 ELSE 1000 END) THEN
  RAISE invalid_parameter_value USING MESSAGE='confirmed swap required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL)
  OR (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=p_occasion AND blueprint=p_blueprint)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 result:=public.swap_blueprint_seats_command_internal(p_first,p_second,p_command_id,
  jsonb_build_object('hash',p_confirmation_hash,'source',to_jsonb(p_source_spots),'target',to_jsonb(p_target_spots),
   'blueprint',p_blueprint,'revision',p_expected_revision));
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF (SELECT count(*) FROM eshop.spots WHERE id IN(p_first,p_second) AND occasion=p_occasion AND blueprint=p_blueprint)<>2 THEN
  RAISE insufficient_privilege USING MESSAGE='swap selection unavailable'; END IF;
 IF NOT p_editor THEN result:=result-'sync'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.swap_blueprint_seats(bigint,bigint,bigint,bigint,bigint,bigint,bigint[],bigint[],bigint,text,uuid,boolean) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.swap_blueprint_seats(bigint,bigint,bigint,bigint,bigint,bigint,bigint[],bigint[],bigint,text,uuid,boolean) TO authenticated;


-- Source: database/functions/blueprint/order_input.sql
-- One form/seat transport builder used by legacy preparation and the atomic
-- replacement aggregate. It prices nothing; finalization owns actual totals.
CREATE OR REPLACE FUNCTION public.blueprint_order_input_internal(p_spots bigint[],p_input jsonb,p_analysis jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE form_key uuid; tickets jsonb;
BEGIN
 IF coalesce(p_input->>'email','')='' THEN RAISE EXCEPTION 'Email is required in input data.'; END IF;
 form_key:=(p_analysis#>>'{order_form,key}')::uuid;
 IF p_input->>'form_key' IS NOT NULL AND p_input->>'form_key' IS DISTINCT FROM form_key::text THEN
  RAISE EXCEPTION 'The active order form changed. Reopen the order.'; END IF;
 IF form_key IS NULL OR NOT EXISTS(SELECT 1 FROM public.forms f WHERE f.key=form_key
  AND f.blueprint=(SELECT blueprint FROM eshop.spots WHERE id=p_spots[1]))
  OR EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint IS DISTINCT FROM
   (SELECT blueprint FROM eshop.spots WHERE id=p_spots[1])) THEN
  RAISE EXCEPTION 'No open form found for this occasion to create the new order.'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('spot',s.id,'fields',
  coalesce(p_input->'ticket_fields'->s.id::text,'[]'::jsonb)) ORDER BY s.id),'[]')
 INTO tickets FROM eshop.spots s WHERE s.id=ANY(p_spots);
 RETURN jsonb_build_object('form',form_key,'ticket',tickets,'lang','cs')
  ||(p_input-'ticket_fields'-'form_key'-'form'-'ticket');
END $$;
REVOKE ALL ON FUNCTION public.blueprint_order_input_internal(bigint[],jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/order_conflicts.sql
-- Same bounded administration projection for requirements and final approval.
-- A buyer belongs to one order; do not repeat contact data for every ticket.
CREATE OR REPLACE FUNCTION public.blueprint_order_conflicts_internal(p_analysis jsonb,p_effects jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=public,extensions AS $$
 WITH tickets AS MATERIALIZED(SELECT c FROM jsonb_array_elements(coalesce(p_analysis->'conflicts','[]')) c),
 grouped AS(SELECT (c->>'order_id')::bigint id,min(c->>'email') email,min(c->>'name') name,min(c->>'surname') surname,
  count(DISTINCT c->>'ticket_id') selected_count,
  jsonb_agg(jsonb_build_object('ticketId',c->'ticket_id','selectedSpotIds',c->'selected_spot_ids',
   'ticketSymbol',c->'ticket_symbol','ticketAmount',c->>'total_price','products',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('productId',p->'id','title',p->'title',
     'amount',p->>'price','currencyCode',upper(btrim(p->>'currency_code')))),'[]')
     FROM jsonb_array_elements(CASE WHEN jsonb_typeof(c->'products')='array' THEN c->'products' ELSE '[]'::jsonb END) p))
   ORDER BY (c->>'ticket_id')::bigint) rows
 FROM tickets GROUP BY (c->>'order_id')::bigint),
 money AS MATERIALIZED(SELECT (e->>'orderId')::bigint id,e->>'afterState' state FROM jsonb_array_elements(coalesce(p_effects,'[]')) e)
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',g.id,'selectedTicketCount',g.selected_count,
  'stateAfter',m.state,'customer',jsonb_build_object('email',g.email,'name',g.name,'surname',g.surname),
  'tickets',g.rows) ORDER BY g.id),'[]') FROM grouped g LEFT JOIN money m ON m.id=g.id
$$;
REVOKE ALL ON FUNCTION public.blueprint_order_conflicts_internal(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/eshop/analyze_new_order_spots.sql
CREATE OR REPLACE FUNCTION public.analyze_new_order_spots(
  p_spot_ids bigint[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_conflicts jsonb;
  v_new_order_items jsonb;
  v_occasion_id BIGINT;
  v_total numeric; v_currency text; v_order_form jsonb;
BEGIN
  -- =======================================================================
  -- 0. VALIDATION & SECURITY
  -- =======================================================================

  -- Handle empty input
  IF p_spot_ids IS NULL OR array_length(p_spot_ids, 1) IS NULL THEN
     RETURN jsonb_build_object('conflicts', '[]'::jsonb, 'new_order_items', '[]'::jsonb);
  END IF;

  -- Get Occasion ID from the first spot
  SELECT occasion INTO v_occasion_id
  FROM eshop.spots
  WHERE id = p_spot_ids[1];

  IF v_occasion_id IS NULL THEN
     RAISE EXCEPTION 'Spot ID % not found.', p_spot_ids[1];
  END IF;

  -- Consistency Check: Ensure all selected spots belong to the SAME occasion
  PERFORM 1
  FROM eshop.spots
  WHERE id = ANY(p_spot_ids)
  AND occasion != v_occasion_id;

  IF FOUND THEN
     RAISE EXCEPTION 'All selected spots must belong to the same occasion.';
  END IF;

  -- Permission Check: User must have "Order View" rights on this occasion
  IF public.can_read_orders(v_occasion_id) IS NOT TRUE THEN
     RAISE EXCEPTION 'Permission denied. User does not have view rights for occasion %.', v_occasion_id;
  END IF;

  IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spot_ids) AND occasion=v_occasion_id)<>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id)) THEN
    RAISE EXCEPTION 'BLUEPRINT_SPOT_SCOPE_MISMATCH'; END IF;
  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion_id]);
  PERFORM public.check_blueprint_selection_units_internal(p_spot_ids);

  -- =======================================================================
  -- 1. IDENTIFY CONFLICTS
  -- =======================================================================
  WITH impacted_base AS (
    SELECT
      s.id as spot_id,
      o.id as order_id,
      o.data as order_data,
      o.state as order_state,
      t.id as ticket_id,
      t.ticket_symbol
    FROM eshop.spots s
    JOIN eshop.order_product_ticket opt ON s.order_product_ticket = opt.id
    JOIN eshop.tickets t ON opt.ticket = t.id
    JOIN eshop.orders o ON opt.order = o.id
    WHERE s.id = ANY(p_spot_ids)
    -- Include any state that implies the spot is technically "occupied"
  ),
  impacted_tickets AS (
    SELECT order_id,order_data,order_state,ticket_id,ticket_symbol,
      array_agg(DISTINCT spot_id ORDER BY spot_id) AS selected_spot_ids
    FROM impacted_base GROUP BY order_id,order_data,order_state,ticket_id,ticket_symbol
  ),
  impacted_enriched AS (
    -- Safely extract the specific ticket from JSON
    SELECT
      ib.*,
      (
        SELECT item
        FROM jsonb_array_elements(ib.order_data->'tickets') item
        WHERE (item->>'id')::bigint = ib.ticket_id
        LIMIT 1
      ) as ticket_json
    FROM impacted_tickets ib
  ),
  order_stats AS (
    -- Calculate if whole order is cancelled
    SELECT
      order_id,
      COUNT(DISTINCT ticket_id) as affected_ticket_count,
      COALESCE(jsonb_array_length(order_data->'tickets'), 0) as total_ticket_count
    FROM impacted_enriched
    GROUP BY order_id, order_data
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'order_id', ie.order_id,
      -- Extract individual fields as requested
      'email', ie.order_data->>'email',
      'name', ie.order_data->>'name',
      'surname', ie.order_data->>'surname',
      'note', ie.order_data->>'note',

      'ticket_id', ie.ticket_id,
      'selected_spot_ids', ie.selected_spot_ids,
      'ticket_symbol', ie.ticket_symbol,
      'is_fully_cancelled', (os.affected_ticket_count >= os.total_ticket_count AND os.total_ticket_count > 0),
      -- The products array from the JSON (Spot + Extras)
      'products', ie.ticket_json->'products',
      -- Sum the price (safely handle nulls)
      'total_price', CASE WHEN jsonb_typeof(ie.ticket_json->'products')='array'
        AND jsonb_array_length(ie.ticket_json->'products')>0
        AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ie.ticket_json->'products') prod WHERE prod->>'price' IS NULL)
        THEN (SELECT SUM((prod->>'price')::numeric) FROM jsonb_array_elements(ie.ticket_json->'products') prod)
        ELSE NULL END
    )
  )
  INTO v_conflicts
  FROM impacted_enriched ie
  JOIN order_stats os ON ie.order_id = os.order_id;

  -- =======================================================================
  -- 2. PREPARE NEW ORDER ITEMS
  -- =======================================================================
  SELECT jsonb_agg(jsonb_build_object(
    'spot_id', s.id,
    'spot_title', s.title,
    'product_title', p.title,
    'price', p.price,
    'currency', p.currency_code
  ))
  INTO v_new_order_items
  FROM eshop.spots s
  LEFT JOIN eshop.products p ON s.product = p.id
  WHERE s.id = ANY(p_spot_ids);

  IF (SELECT count(DISTINCT item->>'currency') FROM jsonb_array_elements(coalesce(v_new_order_items,'[]')) item)>1 THEN RAISE EXCEPTION 'BLUEPRINT_CURRENCY_MISMATCH'; END IF;
  SELECT coalesce(sum((item->>'price')::numeric),0),min(item->>'currency') INTO v_total,v_currency FROM jsonb_array_elements(coalesce(v_new_order_items,'[]')) item;
  SELECT jsonb_build_object('key',f.key,'phone_prefixes',public.get_effective_form_data(f.id)->'phone_prefixes',
    'fields',coalesce((SELECT jsonb_agg(to_jsonb(ff) ORDER BY coalesce(ff."order",0),ff.id)
      FROM public.form_fields ff WHERE ff.form=f.id AND ff.is_required=true
      AND ff.is_hidden=false AND ff.type NOT IN ('ticket','spot','product_type')),'[]'::jsonb))
    INTO v_order_form FROM public.forms f WHERE f.occasion=v_occasion_id AND f.is_open=true
      AND f.blueprint=(SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1])
      AND NOT EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND blueprint IS DISTINCT FROM (SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1]))
    ORDER BY f.type='ticket' DESC,f.id DESC LIMIT 1;
  RETURN jsonb_build_object(
    'conflicts', COALESCE(v_conflicts, '[]'::jsonb),
    'new_order_items', COALESCE(v_new_order_items, '[]'::jsonb),
    'total_price',v_total,'currency',v_currency,'order_form',v_order_form
  );
END;
$$;

-- Source: database/functions/eshop/confirm_blueprint_order_change.sql
CREATE OR REPLACE FUNCTION public.confirm_blueprint_order_change_internal_v1(p_spot_ids bigint[],p_input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE analysis jsonb;details jsonb;tickets bigint[];occ bigint;
BEGIN
 PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
 PERFORM public.check_blueprint_selection_units_internal(p_spot_ids);
 SELECT occasion INTO occ FROM eshop.spots WHERE id=p_spot_ids[1];
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND secret IS NOT NULL
  AND secret_expiration_time>clock_timestamp() AND secret IS DISTINCT FROM (p_input_data->>'secret')::uuid) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_PROTECTED'; END IF;
 analysis:=public.analyze_new_order_spots(p_spot_ids);
 details:=public.blueprint_order_input_internal(p_spot_ids,p_input_data,analysis);
 IF p_input_data->>'payment_method'='stripe' OR EXISTS(
  SELECT 1 FROM eshop.spots s JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
  JOIN eshop.orders o ON o.id=i."order" JOIN eshop.payment_info p ON p.id=o.payment_info
  WHERE s.id=ANY(p_spot_ids) AND p.payment_method='stripe') THEN RAISE EXCEPTION 'STRIPE_REPLACEMENT_UNSUPPORTED'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT x."order" FROM eshop.spots s
  JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket WHERE s.id=ANY(p_spot_ids)));
 PERFORM 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) ORDER BY id FOR UPDATE;
 PERFORM public.check_batch_ticket_print_immutable_internal(ARRAY(SELECT x.ticket FROM eshop.spots s
  JOIN eshop.order_product_ticket x ON x.id=s.order_product_ticket WHERE s.id=ANY(p_spot_ids)));
 SELECT array_agg((e->>'ticket_id')::bigint) INTO tickets FROM jsonb_array_elements(analysis->'conflicts') e
 WHERE e->>'ticket_id' IS NOT NULL;
 IF coalesce(cardinality(tickets),0)>0 THEN PERFORM public.storno_tickets_bulk_internal_v1(tickets); END IF;
 UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL WHERE id=ANY(p_spot_ids);
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 RETURN jsonb_build_object('success',true,'message','Storno performed. Ready to create new order.','orderDetails',details);
EXCEPTION WHEN OTHERS THEN
 RETURN jsonb_build_object('success',false,'message',SQLERRM);
END $$;
REVOKE ALL ON FUNCTION public.confirm_blueprint_order_change_internal_v1(bigint[],jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/order_selection.sql
CREATE OR REPLACE FUNCTION public.blueprint_seat_order_selection_internal(p_occasion bigint,p_blueprint bigint,p_spots bigint[],p_max integer)
RETURNS bigint[] LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE ids bigint[];
BEGIN
 IF coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>p_max OR array_position(p_spots,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT id) FROM unnest(p_spots) id)<>cardinality(p_spots) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid order seat selection'; END IF;
 IF (SELECT count(*) FROM eshop.blueprint_seat_bindings b JOIN eshop.spots s ON s.id=b.spot
  WHERE b.blueprint=p_blueprint AND s.blueprint=p_blueprint AND s.occasion=p_occasion AND b.spot=ANY(p_spots))<>cardinality(p_spots) THEN
  RAISE insufficient_privilege USING MESSAGE='order seat selection unavailable'; END IF;
 -- Expand each requested atomic unit once, including singleton seats. The
 -- canonical unit helper is authoritative; no copy of group semantics in MCP.
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM (
  SELECT DISTINCT coalesce(b.selection_unit::text,'spot:'||b.spot) unit,min(b.spot) representative
  FROM eshop.blueprint_seat_bindings b WHERE b.blueprint=p_blueprint AND b.spot=ANY(p_spots)
  GROUP BY coalesce(b.selection_unit::text,'spot:'||b.spot)) selected
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(selected.representative)) member;
 IF cardinality(ids)>p_max THEN RAISE program_limit_exceeded USING MESSAGE='expanded order selection exceeds operation limit'; END IF;
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(ids) AND occasion=p_occasion AND blueprint=p_blueprint)<>cardinality(ids) THEN
  RAISE insufficient_privilege USING MESSAGE='expanded order selection unavailable'; END IF;
 RETURN ids;
END $$;
REVOKE ALL ON FUNCTION public.blueprint_seat_order_selection_internal(bigint,bigint,bigint[],integer) FROM PUBLIC,anon,authenticated,service_role;

-- Cancelling a selected ticket also releases every other seat on that ticket.
-- Keep new-order targets distinct from this larger affected closure.
CREATE OR REPLACE FUNCTION public.blueprint_order_affected_spots_internal(p_spots bigint[])
RETURNS bigint[] LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public,extensions AS $$
 SELECT ARRAY(SELECT id FROM (
  SELECT unnest(p_spots) id UNION SELECT s.id FROM eshop.spots s
  JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket
  WHERE i.ticket IN(SELECT selected.ticket FROM eshop.spots target
   JOIN eshop.order_product_ticket selected ON selected.id=target.order_product_ticket WHERE target.id=ANY(p_spots))) affected ORDER BY id)
$$;
REVOKE ALL ON FUNCTION public.blueprint_order_affected_spots_internal(bigint[]) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/apply_seat_order_internal.sql
-- Actual cancellation + creation, shared by rollback quote and the one receipt.
-- Commercial calculation remains in the existing cancellation/finalize owners.
CREATE OR REPLACE FUNCTION public.apply_blueprint_seat_order_internal(p_spots bigint[],p_input jsonb,p_command uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE ids bigint[];affected bigint[];seats jsonb;occ bigint;form_id bigint;analysis jsonb;details jsonb;normalized jsonb;products bigint[];
 old_orders bigint[];before_orders jsonb;before_facts jsonb;form_facts jsonb;prepared jsonb;created jsonb;
 effects jsonb;new_order eshop.orders;new_products jsonb;semantic jsonb;revision jsonb;
BEGIN
 ids:=ARRAY(SELECT DISTINCT id FROM unnest(p_spots) id WHERE id IS NOT NULL ORDER BY id);
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id=ANY(ids);
 IF occ IS NULL OR cardinality(ids)=0 OR cardinality(ids)>20000 OR
  (SELECT count(*) FROM eshop.spots WHERE id=ANY(ids) AND occasion=occ)<>cardinality(ids)
  OR public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 affected:=public.blueprint_order_affected_spots_internal(ids);
 PERFORM public.check_blueprint_swap_scope_internal(occ,affected);
 analysis:=public.analyze_new_order_spots(ids);
 details:=public.blueprint_order_input_internal(ids,p_input,analysis);
 SELECT id INTO form_id FROM public.forms WHERE key=(details->>'form')::uuid;
 -- Lock destination and existing forms together, before any order/product child.
 PERFORM 1 FROM public.forms WHERE id IN(SELECT form_id UNION SELECT o.form
  FROM eshop.orders o JOIN eshop.order_product_ticket i ON i."order"=o.id
  JOIN eshop.spots s ON s.order_product_ticket=i.id WHERE s.id=ANY(ids)) ORDER BY id FOR UPDATE;
 analysis:=public.analyze_new_order_spots(ids);
 IF analysis#>>'{order_form,key}' IS DISTINCT FROM details->>'form' THEN
  RAISE serialization_failure USING MESSAGE='order form changed; retry the same command'; END IF;
 normalized:=public.normalize_form_ticket_answers_internal(form_id,details->'ticket');
 SELECT ARRAY(SELECT DISTINCT (f->>'product_type')::bigint FROM jsonb_array_elements(normalized) t
  CROSS JOIN LATERAL jsonb_array_elements(t->'fields') f WHERE f->>'product_type' IS NOT NULL ORDER BY 1) INTO products;
 IF EXISTS(SELECT 1 FROM unnest(products) requested(id) LEFT JOIN eshop.products p ON p.id=requested.id
  LEFT JOIN eshop.product_types pt ON pt.id=p.product_type WHERE p.id IS NULL OR pt.occasion IS DISTINCT FROM occ) THEN
  RAISE insufficient_privilege USING MESSAGE='order product scope unavailable'; END IF;
 PERFORM public.lock_spot_assignment_scope_internal(affected,'{}'::bigint[],true,products);
 IF affected IS DISTINCT FROM public.blueprint_order_affected_spots_internal(ids) THEN
  RAISE serialization_failure USING MESSAGE='order seat parents changed; retry the same command'; END IF;
 PERFORM public.check_blueprint_swap_scope_internal(occ,affected);
 IF EXISTS(SELECT 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
  WHERE p.id=ANY(products) AND pt.occasion IS DISTINCT FROM occ) THEN
  RAISE insufficient_privilege USING MESSAGE='order product scope unavailable'; END IF;
 PERFORM public.check_blueprint_selection_units_internal(ids);
 SELECT array_agg(DISTINCT i."order") INTO old_orders FROM eshop.spots s
 JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket WHERE s.id=ANY(ids);
 before_orders:=public.order_payment_snapshot_internal(old_orders);
 -- Customer facts and all required form definitions bind consent privately;
 -- the scoped MCP projection never receives existing customer identities.
 analysis:=public.analyze_new_order_spots(ids);
 SELECT to_jsonb(f)-'updated_at'-'created_at' INTO form_facts FROM public.forms f WHERE id=form_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'revision',b.layout_revision) ORDER BY b.id),'[]')
 INTO revision FROM eshop.blueprints b WHERE b.id IN(SELECT blueprint FROM eshop.spots WHERE id=ANY(affected));
 WITH lifecycle AS MATERIALIZED (SELECT * FROM public.blueprint_spot_facts_internal(occ,affected))
 SELECT coalesce(jsonb_object_agg(s.id::text,jsonb_build_object('spot',s.id,'product',s.product,'price',p.price,'currency',p.currency_code,
  'item',s.order_product_ticket,'ticketState',t.state,'hold',s.secret,'expires',extract(epoch FROM s.secret_expiration_time),'state',lifecycle.state,'ticket',i.ticket,'order',i."order")),'{}')
 INTO before_facts FROM eshop.spots s LEFT JOIN eshop.products p ON p.id=s.product
 LEFT JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket LEFT JOIN eshop.tickets t ON t.id=i.ticket LEFT JOIN lifecycle ON lifecycle.id=s.id WHERE s.id=ANY(affected);
 prepared:=public.confirm_blueprint_order_change_internal_v1(ids,p_input);
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 IF coalesce((prepared->>'success')::boolean,false) IS NOT TRUE THEN
  RAISE check_violation USING MESSAGE='replacement preparation rejected',DETAIL=prepared::text; END IF;
 created:=public.create_ticket_order_internal_v1(prepared->'orderDetails');
 IF coalesce((created->>'code')::integer,500)<>200 THEN
  RAISE check_violation USING MESSAGE='replacement order rejected',DETAIL=created::text; END IF;
 PERFORM public.enqueue_ticket_order_confirmation_v1(p_command,occ,created,coalesce(p_input->>'lang',prepared#>>'{orderDetails,lang}'));
 SELECT * INTO new_order FROM eshop.orders WHERE id=(created#>>'{order,id}')::bigint;
 IF created#>>'{order,payment_info,payment_method}'='stripe' THEN
  RAISE check_violation USING MESSAGE='STRIPE_REPLACEMENT_UNSUPPORTED'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',id,'beforeAmount',(before_orders->id::text->>'amount')::numeric,
  'afterAmount',price,'delta',price-(before_orders->id::text->>'amount')::numeric,'currencyCode',currency_code,
  'beforeState',before_orders->id::text->>'state','afterState',state) ORDER BY id),'[]')
 INTO effects FROM eshop.orders WHERE id=ANY(old_orders);
 WITH ticket_spots AS MATERIALIZED (SELECT s.id,i.ticket FROM eshop.spots s
  JOIN eshop.order_product_ticket i ON i.id=s.order_product_ticket WHERE s.id=ANY(ids))
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',s.id,'productId',(p->>'id')::bigint,'title',p->'title',
  'amount',p->>'price','currencyCode',p->'currency_code') ORDER BY s.id,(p->>'id')::bigint,(p->>'price')::numeric),'[]')
 INTO new_products FROM jsonb_array_elements(new_order.data->'tickets') t
 JOIN ticket_spots s ON s.ticket=(t->>'id')::bigint CROSS JOIN LATERAL jsonb_array_elements(t->'products') p;
 WITH lifecycle AS MATERIALIZED (SELECT * FROM public.blueprint_spot_facts_internal(occ,affected))
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',s.id,'blueprintId',s.blueprint,'blueprintTitle',b.title,'title',s.title,
  'stateBefore',before_facts->s.id::text->'state','stateAfter',f.state,
  'previousOrderId',before_facts->s.id::text->'order','previousTicketId',before_facts->s.id::text->'ticket',
  'productId',s.product,'productTitle',p.title) ORDER BY s.id),'[]')
 INTO seats FROM eshop.spots s LEFT JOIN eshop.products p ON p.id=s.product LEFT JOIN eshop.blueprints b ON b.id=s.blueprint LEFT JOIN lifecycle f ON f.id=s.id WHERE s.id=ANY(affected);
 semantic:=jsonb_build_object('spotIds',ids,'affectedSpotIds',affected,
  'releasedSpotIds',ARRAY(SELECT id FROM unnest(affected) id WHERE NOT id=ANY(ids)),
  'seats',seats,'blueprints',revision,'formKey',details->'form','orders',effects,
  'newOrder',jsonb_build_object('amount',new_order.price::text,'currencyCode',new_order.currency_code,
   'state',new_order.state,'paymentMethod',created#>'{order,payment_info,payment_method}',
   'ticketCount',(SELECT count(DISTINCT ticket) FROM eshop.order_product_ticket WHERE "order"=new_order.id),
   'products',new_products));
 PERFORM public.check_occasion_writable(occ);
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 RETURN jsonb_build_object('result',created,'quote',semantic,'analysis',analysis,
  'confirmationHash',encode(extensions.digest(convert_to(jsonb_build_object('actor',auth.uid(),'quote',semantic,
   'input',p_input,'beforeOrders',before_orders,'facts',before_facts,'analysis',analysis,'form',form_facts,
   'paymentRecipient',jsonb_build_object('account',created#>'{order,payment_info,account_number}',
    'accountLabel',created#>'{order,payment_info,account_number_human_readable}',
    'creditor',created#>'{order,payment_info,creditor_name}','deposit',created#>'{order,payment_info,deposit_amount}'),
   'effectiveForm',created#>'{order,form,data}','occasionFeatures',created#>'{order,occasion,features}')::text,'UTF8'),'sha256'),'hex'));
END $$;
REVOKE ALL ON FUNCTION public.apply_blueprint_seat_order_internal(bigint[],jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/order_quote.sql
-- Validate one final typed quote before retaining any confirmed write effects.
CREATE OR REPLACE FUNCTION public.blueprint_seat_order_quote_internal(p_effect jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE quote jsonb:=p_effect->'quote';money jsonb;products jsonb;
BEGIN
 IF coalesce(quote#>>'{newOrder,amount}','')!~'^-?[0-9]+(\.[0-9]+)?$'
  OR length(quote#>>'{newOrder,amount}')>40
  OR coalesce(btrim(quote#>>'{newOrder,currencyCode}'),'')!~'^[A-Za-z]{3}$'
  OR coalesce(length(quote#>>'{newOrder,state}'),0) NOT BETWEEN 1 AND 64
  OR quote#>>'{newOrder,paymentMethod}' IS DISTINCT FROM 'bank'
  OR (quote#>>'{newOrder,ticketCount}')::int IS DISTINCT FROM jsonb_array_length(quote->'spotIds')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(quote#>'{newOrder,products}') p
    WHERE coalesce(p->>'amount','')!~'^-?[0-9]+(\.[0-9]+)?$' OR length(p->>'amount')>40
    OR coalesce(btrim(p->>'currencyCode'),'')!~'^[A-Za-z]{3}$')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(quote->'spotIds') requested(id)
    WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(quote#>'{newOrder,products}') p WHERE p->>'spotId'=requested.id)) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_ORDER_MONEY_UNAVAILABLE'; END IF;
 money:=public.project_order_amount_changes_internal(quote->'orders');
 SELECT coalesce(jsonb_agg(p||jsonb_build_object('currencyCode',upper(btrim(p->>'currencyCode')))),'[]') INTO products
 FROM jsonb_array_elements(quote#>'{newOrder,products}') p;
 RETURN jsonb_set(jsonb_set(jsonb_set(quote,'{orders}',money),'{newOrder,currencyCode}',to_jsonb(upper(btrim(quote#>>'{newOrder,currencyCode}')))),
  '{newOrder,products}',products);
END $$;
REVOKE ALL ON FUNCTION public.blueprint_seat_order_quote_internal(jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/order_rejection.sql
-- Only structured domain errors cross the new preview/command boundary.
CREATE OR REPLACE FUNCTION public.blueprint_order_rejection_internal(p_message text,p_detail text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE failure jsonb:='{}';reason text;result jsonb;
BEGIN
 BEGIN
  IF left(p_detail,1)='{' THEN failure:=p_detail::jsonb;
  ELSIF left(p_message,1)='{' THEN failure:=p_message::jsonb; END IF;
 EXCEPTION WHEN invalid_text_representation THEN failure:='{}';
 END;
 reason:=coalesce(failure->>'errorCode',failure->>'message',p_message);
 IF reason IS NULL OR NOT reason=ANY(ARRAY['REQUIRED_FIELD_MISSING','PRODUCT_CAPACITY_EXCEEDED','FORM_CAPACITY_EXCEEDED',
  'PRODUCT_SCOPE_MISMATCH','FORM_FIELD_SCOPE_MISMATCH','FORM_FIELD_TYPE_MISMATCH','FORM_FIELD_AMBIGUOUS','FORM_FIELD_VALUE_CONFLICT',
  'BATCH_TICKET_PRINT_IMMUTABLE','BLUEPRINT_ORDER_MONEY_UNAVAILABLE','BLUEPRINT_SEAT_PROTECTED','BLUEPRINT_SELECTION_UNIT_USED',
  'BLUEPRINT_INCOMPLETE_SELECTION_UNIT','STRIPE_REPLACEMENT_UNSUPPORTED','BLUEPRINT_CURRENCY_MISMATCH']) THEN
  reason:='BLUEPRINT_ORDER_INPUT_OR_STATE_REJECTED'; END IF;
 result:=jsonb_build_object('code',409,'reason',reason);
 IF reason='REQUIRED_FIELD_MISSING' AND coalesce(failure->>'fieldId','')~'^[1-9][0-9]{0,14}$' THEN
  result:=result||jsonb_build_object('fieldId',(failure->>'fieldId')::bigint); END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.blueprint_order_rejection_internal(text,text) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/blueprint/order_command_internal.sql
CREATE OR REPLACE FUNCTION public.replace_blueprint_order_command_internal(
 p_spot_ids bigint[],p_input_data jsonb,p_command_id uuid,p_confirmation jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid();occ bigint;started jsonb;fingerprint text;before_users uuid[];
 effect jsonb;result jsonb;quote jsonb;ids bigint[];failure text;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id=ANY(p_spot_ids);
 IF actor IS NULL OR occ IS NULL OR coalesce(cardinality(p_spot_ids),0)=0
  OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spot_ids) AND occasion=occ)<>
    cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
  OR public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 fingerprint:=encode(extensions.digest(convert_to((jsonb_build_object('spots',p_spot_ids,'input',p_input_data)
  ||CASE WHEN p_confirmation IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('confirmation',p_confirmation) END)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.order.replace',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN public.project_local_payment_reference_order_internal(started->'response'); END IF;
 SELECT coalesce(array_agg(ou."user"),'{}') INTO before_users FROM public.occasion_users ou WHERE ou.occasion=occ;
 BEGIN
  ids:=CASE WHEN p_confirmation IS NULL THEN p_spot_ids ELSE
   public.blueprint_seat_order_selection_internal(occ,(p_confirmation->>'blueprint')::bigint,p_spot_ids,20000) END;
  effect:=public.apply_blueprint_seat_order_internal(ids,p_input_data,p_command_id);
  result:=effect->'result'||jsonb_build_object('paymentPreparationPolicy','leased_keep_pending');
  IF p_confirmation IS NOT NULL THEN
   quote:=public.blueprint_seat_order_quote_internal(effect);
   IF effect->>'confirmationHash' IS DISTINCT FROM p_confirmation->>'hash'
    OR quote->'spotIds' IS DISTINCT FROM p_confirmation->'targets'
    OR quote->'affectedSpotIds' IS DISTINCT FROM p_confirmation->'affected'
    OR quote->'blueprints' IS DISTINCT FROM p_confirmation->'blueprints' THEN
    RAISE SQLSTATE 'BP002' USING MESSAGE='BLUEPRINT_ORDER_CHANGED'; END IF;
  END IF;
 EXCEPTION WHEN SQLSTATE 'BP002' THEN
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,jsonb_build_object('reason','BLUEPRINT_ORDER_CHANGED'));
 WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
 WHEN check_violation THEN
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',CASE WHEN p_confirmation IS NULL THEN 400 ELSE 409 END,
   CASE WHEN p_confirmation IS NULL AND left(failure,1)='{' THEN failure::jsonb
   ELSE public.blueprint_order_rejection_internal(SQLERRM,failure) END);
 WHEN OTHERS THEN
  IF p_confirmation IS NULL THEN RAISE; END IF;
  IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,public.blueprint_order_rejection_internal(SQLERRM,NULL));
 END;
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 IF p_confirmation IS NOT NULL THEN result:=result||jsonb_build_object('quote',quote); END IF;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.order.replace',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',result#>>'{order,id}','operation','insert',
   'safeLabel','Blueprint order replacement','changedFields',jsonb_build_array('cancellations','tickets','products','allocations','membership'))),
  before_users,result);
END $$;
REVOKE ALL ON FUNCTION public.replace_blueprint_order_command_internal(bigint[],jsonb,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/eshop_orders/replace_blueprint_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.confirm_blueprint_order_change_client_sync_v1(
  p_spot_ids bigint[],p_input_data jsonb,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before_users uuid[];
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF public.payment_reference_scope_enabled_internal((SELECT id FROM public.forms WHERE occasion=v_occasion ORDER BY id LIMIT 1)) THEN
    RETURN jsonb_build_object('status','rejected','code',409,'data',jsonb_build_object('errorCode','ATOMIC_REPLACEMENT_REQUIRED')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.prepare_replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN public.project_local_payment_reference_order_internal(v_begin->'response'); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.confirm_blueprint_order_change_internal_v1(
    p_spot_ids,p_input_data);
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,v_result); END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.prepare_replace',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',NULL,
      'operation','update','safeLabel','Blueprint order replacement',
      'changedFields',jsonb_build_array('cancellations','allocations'))),
    v_before_users,v_result);
END; $$;
REVOKE ALL ON FUNCTION public.confirm_blueprint_order_change_client_sync_v1(
  bigint[],jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_blueprint_order_change_client_sync_v1(
  bigint[],jsonb,uuid) TO authenticated;

-- Released clients keep their exact original fingerprint and response projection.
CREATE OR REPLACE FUNCTION public.replace_blueprint_order_client_sync_v1(p_spot_ids bigint[],p_input_data jsonb,p_command_id uuid)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.replace_blueprint_order_command_internal(p_spot_ids,p_input_data,p_command_id,NULL)
$$;
REVOKE ALL ON FUNCTION public.replace_blueprint_order_client_sync_v1(bigint[],jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.replace_blueprint_order_client_sync_v1(bigint[],jsonb,uuid) TO authenticated;


-- Source: database/functions/blueprint/seat_orders.sql
CREATE OR REPLACE FUNCTION public.preview_blueprint_seat_order(p_occasion bigint,p_organization bigint,p_unit bigint,
 p_blueprint bigint,p_spots bigint[],p_input jsonb DEFAULT NULL,p_editor boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE ids bigint[];affected bigint[];analysis jsonb;effect jsonb;quote jsonb;result jsonb;conflicts jsonb;items jsonb;failure text;
BEGIN
 IF p_editor IS NULL OR (p_input IS NOT NULL AND (jsonb_typeof(p_input)<>'object'
  OR octet_length(p_input::text)>(CASE WHEN p_editor THEN 4194304 ELSE 1048576 END))) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid order preview'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL) THEN
  RAISE insufficient_privilege USING MESSAGE='canonical blueprint unavailable'; END IF;
 ids:=public.blueprint_seat_order_selection_internal(p_occasion,p_blueprint,p_spots,CASE WHEN p_editor THEN 20000 ELSE 1000 END);
 affected:=public.blueprint_order_affected_spots_internal(ids);
 IF cardinality(affected)>(CASE WHEN p_editor THEN 20000 ELSE 1000 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='affected order seats exceed operation limit'; END IF;
 PERFORM public.check_blueprint_swap_scope_internal(p_occasion,affected);
 IF p_input IS NULL THEN
  BEGIN
   analysis:=public.analyze_new_order_spots(ids);
  EXCEPTION WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
   PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
   GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
   RETURN public.blueprint_order_rejection_internal(SQLERRM,failure);
  END;
  conflicts:=public.blueprint_order_conflicts_internal(analysis);
  SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',i->'spot_id','title',i->'spot_title','productTitle',i->'product_title',
   'amount',i->>'price','currencyCode',upper(btrim(i->>'currency'))) ORDER BY (i->>'spot_id')::bigint),'[]')
  INTO items FROM jsonb_array_elements(analysis->'new_order_items') i;
  result:=jsonb_build_object('code',200,'mode','requirements','actorId',auth.uid(),'occasionId',p_occasion,'blueprintId',p_blueprint,
   'requestedSpotIds',p_spots,'spotIds',ids,'affectedSpotIds',affected,'conflicts',conflicts,'items',items,
   'seatSubtotal',CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(analysis->'new_order_items') i WHERE i->>'price' IS NULL OR i->>'currency' IS NULL)
     THEN NULL ELSE analysis->>'total_price' END,'currencyCode',upper(btrim(analysis->>'currency')),
   'formKey',analysis#>'{order_form,key}','requiredFields',coalesce(analysis#>'{order_form,fields}','[]'),
   'phonePrefixes',analysis#>'{order_form,phone_prefixes}');
 ELSE
  -- The real creation/cancellation and queued side effects are all rolled back.
  -- Generated order/ticket IDs and email keys never enter the stable quote hash.
  BEGIN
   effect:=public.apply_blueprint_seat_order_internal(ids,p_input,extensions.gen_random_uuid());
   quote:=public.blueprint_seat_order_quote_internal(effect);
   RAISE SQLSTATE 'BP001' USING MESSAGE='rollback successful order quote';
  EXCEPTION WHEN SQLSTATE 'BP001' THEN NULL;
  WHEN serialization_failure OR deadlock_detected OR insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
   PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
   GET STACKED DIAGNOSTICS failure=PG_EXCEPTION_DETAIL;
   RETURN public.blueprint_order_rejection_internal(SQLERRM,failure);
  END;
  result:=jsonb_build_object('code',200,'mode','quote','actorId',auth.uid(),'occasionId',p_occasion,'blueprintId',p_blueprint,
   'requestedSpotIds',p_spots,'confirmationHash',effect->>'confirmationHash','quote',quote,
   'conflicts',public.blueprint_order_conflicts_internal(effect->'analysis',quote->'orders'));
 END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF octet_length(result::text)>(CASE WHEN p_editor THEN 8388608 ELSE 1048576 END) THEN
  RAISE program_limit_exceeded USING MESSAGE='order preview exceeds payload limit'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.preview_blueprint_seat_order(bigint,bigint,bigint,bigint,bigint[],jsonb,boolean) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.preview_blueprint_seat_order(bigint,bigint,bigint,bigint,bigint[],jsonb,boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.create_blueprint_seat_order(p_occasion bigint,p_organization bigint,p_unit bigint,
 p_blueprint bigint,p_spots bigint[],p_input jsonb,p_target_spots bigint[],p_affected_spots bigint[],p_blueprints jsonb,
 p_confirmation_hash text,p_command_id uuid,p_editor boolean DEFAULT false,p_expected_actor uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;max_seats integer:=CASE WHEN p_editor THEN 20000 ELSE 1000 END;
BEGIN
 IF p_expected_actor IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN
  RAISE insufficient_privilege USING MESSAGE='confirmed order actor changed'; END IF;
 IF p_editor IS NULL OR p_command_id IS NULL OR p_confirmation_hash IS NULL OR p_confirmation_hash!~'^[0-9a-f]{64}$'
  OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>(CASE WHEN p_editor THEN 4194304 ELSE 1048576 END)
  OR coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>max_seats
  OR coalesce(cardinality(p_target_spots),0)=0 OR cardinality(p_target_spots)>max_seats
  OR coalesce(cardinality(p_affected_spots),0)=0 OR cardinality(p_affected_spots)>max_seats
  OR jsonb_typeof(p_blueprints) IS DISTINCT FROM 'array' THEN
  RAISE invalid_parameter_value USING MESSAGE='confirmed seat order required'; END IF;
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion AND layout IS NOT NULL)
  OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion AND blueprint=p_blueprint)<>cardinality(p_spots) THEN
  RAISE insufficient_privilege USING MESSAGE='order seat selection unavailable'; END IF;
 result:=public.replace_blueprint_order_command_internal(p_spots,p_input,p_command_id,
  jsonb_build_object('hash',p_confirmation_hash,'blueprint',p_blueprint,'targets',p_target_spots,
   'affected',p_affected_spots,'blueprints',p_blueprints));
 PERFORM public.check_product_catalog_scope_internal(p_occasion,p_organization,p_unit,true,true);
 IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND occasion=p_occasion AND blueprint=p_blueprint)<>cardinality(p_spots) THEN
  RAISE insufficient_privilege USING MESSAGE='order seat selection unavailable'; END IF;
 IF NOT p_editor THEN
  result:=result-'sync';
  IF result->>'status' IN('applied','unchanged') THEN
   result:=jsonb_set(result,'{data}',jsonb_build_object('code',result#>'{data,code}',
    'orderId',result#>'{data,order,id}','orderSymbol',result#>'{data,order,order_symbol}','quote',jsonb_set((result#>'{data,quote}')-'seats','{newOrder}',(result#>'{data,quote,newOrder}')-'products')));
  END IF;
 END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.create_blueprint_seat_order(bigint,bigint,bigint,bigint,bigint[],jsonb,bigint[],bigint[],jsonb,text,uuid,boolean,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.create_blueprint_seat_order(bigint,bigint,bigint,bigint,bigint[],jsonb,bigint[],bigint[],jsonb,text,uuid,boolean,uuid) TO authenticated;


